local WalkingStickMaker = {}
local PRODUCTS = {
    simple_oak_cane = { name = "Preprost hrastov sprehodalni palica", woodCost = 2, leatherCost = 1, time = 3, cost = 50, beauty = 18, happiness = 1, prestige = 2, description = "Preprost hrastov sprehodalni palica za sprehode." },
    carved_wood_cane = { name = "Izrezljana lesena palica", woodCost = 2, leatherCost = 1, time = 6, cost = 140, beauty = 32, happiness = 2, prestige = 5, description = "Izrezljana lesena palica za trgovce." },
    silver_handle_cane = { name = "Srebrnorokavna palica", woodCost = 2, silverCost = 1, leatherCost = 1, time = 9, cost = 340, beauty = 48, happiness = 2, prestige = 10, description = "Srebrnorokavna palica za plemiče." },
    gold_trimmed_cane = { name = "Zlatookrasna palica", woodCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, time = 13, cost = 800, beauty = 62, happiness = 3, prestige = 18, description = "Zlatookrasna palica za visoke plemiče." },
    jewel_pommel_cane = { name = "Draguljnogrbi palica", woodCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 17, cost = 1800, beauty = 78, happiness = 5, prestige = 30, description = "Palica z draguljnim grbičem za visoko plemstvo." },
    royal_grand_cane = { name = "Kraljevski veliki palica", woodCost = 3, goldCost = 2, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 4200, beauty = 92, happiness = 12, prestige = 60, description = "Velika kraljevska palica z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    cane_workshop = { name = "Palica delavnica", cost = { gold = 220, wood = 140, stone = 100, leather = 6 }, upkeep = 5, qualityBonus = 5 },
    stick_loft = { name = "Palica podstrešje", cost = { gold = 880, wood = 280, stone = 220, silver = 6 }, upkeep = 20, qualityBonus = 18 },
    master_cane_atelier = { name = "Mojstrski palica atelje", cost = { gold = 2500, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_cane_palace = { name = "Kraljevska palica palača", cost = { gold = 10500, wood = 600, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
WalkingStickMaker.woodStock = 16; WalkingStickMaker.leatherStock = 12; WalkingStickMaker.silverStock = 6; WalkingStickMaker.goldStock = 6; WalkingStickMaker.jewelStock = 4; WalkingStickMaker.pearlStock = 4
WalkingStickMaker.productStock = {}; WalkingStickMaker.buildings = {}; WalkingStickMaker.maker = nil; WalkingStickMaker.activeMaking = {}; WalkingStickMaker.totalProducts = 0; WalkingStickMaker.dayTimer = 0
function WalkingStickMaker.init() WalkingStickMaker.woodStock=16; WalkingStickMaker.leatherStock=12; WalkingStickMaker.silverStock=6; WalkingStickMaker.goldStock=6; WalkingStickMaker.jewelStock=4; WalkingStickMaker.pearlStock=4; WalkingStickMaker.productStock={}; WalkingStickMaker.buildings={}; WalkingStickMaker.maker=nil; WalkingStickMaker.activeMaking={}; WalkingStickMaker.totalProducts=0; WalkingStickMaker.dayTimer=0; print("[WalkingStickMaker] Royal Walking Stick Maker System initialized (6 products, 4 buildings)") end
function WalkingStickMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WalkingStickMaker.maker={name=n or ("Palicar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Palicar najet: %s (spretnost: %d)",WalkingStickMaker.maker.name,s),"success") end; return true end
function WalkingStickMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WalkingStickMaker.build(id) local ok,e=WalkingStickMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WalkingStickMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WalkingStickMaker.getQualityBonus() local b=0; for _,bd in ipairs(WalkingStickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WalkingStickMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and WalkingStickMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WalkingStickMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WalkingStickMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WalkingStickMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WalkingStickMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WalkingStickMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WalkingStickMaker.buildings==0 then return false,"Potrebna palica delavnica" end; if not WalkingStickMaker.maker then return false,"Potreben palicar" end; return true end
function WalkingStickMaker.make(pt,qty) qty=qty or 1; local ok,e=WalkingStickMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then WalkingStickMaker.woodStock=WalkingStickMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WalkingStickMaker.leatherStock=WalkingStickMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WalkingStickMaker.silverStock=WalkingStickMaker.silverStock-d.silverCost*qty end; if d.goldCost then WalkingStickMaker.goldStock=WalkingStickMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WalkingStickMaker.jewelStock=WalkingStickMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WalkingStickMaker.pearlStock=WalkingStickMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WalkingStickMaker.maker then t=math.max(1,t-math.floor(WalkingStickMaker.maker.skill/13)) end; table.insert(WalkingStickMaker.activeMaking,{id="cane_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WalkingStickMaker.completeMaking(m) local q=1.0+(WalkingStickMaker.getQualityBonus()/100); if WalkingStickMaker.maker then q=q+(WalkingStickMaker.maker.skill/140) end; q=math.min(2.5,q); WalkingStickMaker.productStock[m.productType]=(WalkingStickMaker.productStock[m.productType] or 0)+m.quantity; WalkingStickMaker.totalProducts=WalkingStickMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WalkingStickMaker.maker then WalkingStickMaker.maker.itemsMade=WalkingStickMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WalkingStickMaker.maker.skill=math.min(100,WalkingStickMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Palica izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"cane.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function WalkingStickMaker.update(dt) if not _G.state then return end; WalkingStickMaker.dayTimer=WalkingStickMaker.dayTimer+dt; if WalkingStickMaker.dayTimer>=30 then WalkingStickMaker.dayTimer=0; for i=#WalkingStickMaker.activeMaking,1,-1 do local m=WalkingStickMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WalkingStickMaker.completeMaking(m); table.remove(WalkingStickMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WalkingStickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WalkingStickMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WalkingStickMaker.getStats() return {woodStock=WalkingStickMaker.woodStock,leatherStock=WalkingStickMaker.leatherStock,silverStock=WalkingStickMaker.silverStock,goldStock=WalkingStickMaker.goldStock,jewelStock=WalkingStickMaker.jewelStock,pearlStock=WalkingStickMaker.pearlStock,productStock=WalkingStickMaker.productStock,numBuildings=#WalkingStickMaker.buildings,hasMaker=WalkingStickMaker.maker~=nil,makerName=WalkingStickMaker.maker and WalkingStickMaker.maker.name or "—",makerSkill=WalkingStickMaker.maker and WalkingStickMaker.maker.skill or 0,activeMaking=#WalkingStickMaker.activeMaking,totalProducts=WalkingStickMaker.totalProducts} end
return WalkingStickMaker
